LOCK TABLES `poet` WRITE;
/*!40000 ALTER TABLE `poet` DISABLE KEYS */;
INSERT INTO `poet` VALUES (1,'杜甫',4,712,770,'河南巩县（今河南巩义）','字子美，自号少陵野老，唐代伟大的现实主义诗人，被尊为\"诗圣\"，其诗被誉为\"诗史\"，与李白并称\"大李杜\"。生于巩县，祖籍襄阳。历经安史之乱，曾任左拾遗、检校工部员外郎，世称杜工部。代表作有\"三吏\"\"三别\"《望岳》《登高》《春望》等。','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/poets/杜甫_画像_01.jpg\"]',NULL,'现实主义（沉郁顿挫）','2026-06-17 18:00:50','2026-07-08 01:21:29'),(2,'黄景仁',8,1749,1783,'常州府武进（今江苏常州武进）','字汉镛，一字仲则，号鹿菲子。清代诗人，常州武进人，黄庭坚后裔。四岁而孤，一生困顿，客游四方。诗学李白，多抒穷愁凄怆之情，被推为\"乾隆六十年间第一\"。代表作《两当轩集》。',NULL,NULL,'诗学太白','2026-06-17 18:00:50','2026-07-08 01:43:14'),(3,'曾巩',5,1019,1083,'建昌军南丰（今江西南丰）','字子固，北宋建昌军南丰人，唐宋八大家之一。少有文名，为欧阳修赏识，嘉祐二年进士及第，历任太平州司法参军、馆阁校勘、越州通判及齐、襄、洪、福等州知州，政绩显著，元丰末官至中书舍人。散文含蓄典重、雍容平易，为北宋诗文革新运动积极骨干，著有《元丰类稿》。','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/poets/曾巩_画像_01.jpg\"]',NULL,'北宋古文运动（唐宋八大家）','2026-06-17 18:00:50','2026-07-08 01:43:12'),(4,'晏璧',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(5,'赵孟頫',6,1254,1322,'吴兴（今浙江湖州）','字子昂，号松雪道人。宋太祖赵匡胤十一世孙，宋末元初官员、书法家、画家、文学家。宋亡后隐居，至元二十三年被荐入元朝，历仕世祖至英宗四朝，官至翰林学士承旨、荣禄大夫。创\"赵体\"楷书，与欧阳询、颜真卿、柳公权并称\"楷书四大家\"，倡导\"书画同源\"，开元代文人画新风。代表作《松雪斋文集》《鹊华秋色图》。','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/poets/赵孟頫_画像_01.jpg\"]',NULL,'元代文人画派、赵体楷书','2026-06-17 18:00:50','2026-07-08 01:21:30'),(6,'李白',4,701,762,'蜀郡绵州昌隆青莲乡（今四川江油）','字太白，号青莲居士，又号谪仙人，唐代伟大的浪漫主义诗人，被后人誉为\"诗仙\"，与杜甫并称\"大李杜\"。生于蜀郡绵州昌隆青莲乡，祖籍陇西成纪。曾供奉翰林，安史之乱中因入永王幕获罪流放夜郎，遇赦后病逝于当涂。代表作有《将进酒》《蜀道难》《早发白帝城》等。','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/poets/李白_画像_01.jpg\"]',NULL,'浪漫主义（豪迈奔放、清新飘逸）','2026-06-17 18:00:50','2026-07-08 01:21:29'),(7,'元好问',9,1190,1257,'太原秀容（今山西忻州）','字裕之，号遗山，世称遗山先生。金末至大蒙古国时期文学家、历史学家，被尊为\"北方文雄\"\"一代文宗\"。七岁能诗，兴定五年进士，官至尚书省掾、左司都事。金亡不仕，潜心编纂《中州集》以诗存史。其词为金代一朝之冠，代表作《摸鱼儿·雁丘词》《论诗三十首》。','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/poets/元好问_画像_01.jpg\"]',NULL,'沉郁悲凉（丧乱诗派）','2026-06-17 18:00:50','2026-07-08 01:21:30'),(8,'胡缵宗',7,1480,1560,'陕西巩昌府秦州秦安（今甘肃天水秦安）','字孝思，一字世甫，号可泉，亦号鸟鼠山人。明代学者、诗人、书法家。正德三年进士，任翰林院检讨，历官嘉定州判官、安庆及苏州知府、山东及河南巡抚。为官爱民礼士，后因诗狱削籍为民。著《鸟鼠山人集》。','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/poets/胡缵宗_画像_01.jpg\"]',NULL,'现实主义诗歌，陇右诗派','2026-06-17 18:00:50','2026-07-08 01:43:13'),(9,'王昶',8,1724,1806,'青浦（今上海青浦）','字德甫，号述庵，又号兰泉，学者称兰泉先生。清代学者、诗人，江苏青浦（今上海青浦）人。乾隆十九年进士，官至刑部右侍郎。早年为\"吴中七子\"之一，工诗古文辞，通经学，精于考证，时称通儒。词承浙派轨范，著有《春融堂集》《金石萃编》，辑《湖海诗传》《国朝词综》。',NULL,NULL,'浙西词派（吴中七子）','2026-06-17 18:00:50','2026-07-08 01:43:14'),(10,'刘藻',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(11,'王守仁',7,1472,1529,'绍兴府余姚（今浙江余姚）','字伯安，号阳明，明代绍兴府余姚人，思想家、哲学家、军事家、教育家，心学集大成者。弘治十二年进士，因忤刘瑾贬谪贵州龙场，悟\"知行合一\"之道。后平定宁王之乱，官至南京兵部尚书，封新建伯。创姚江学派，倡\"致良知\"说，与孔孟朱并称\"孔孟朱王\"。代表作《传习录》《王文成公全书》。','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/poets/王守仁_画像_01.jpg\"]',NULL,'姚江学派（阳明心学）','2026-06-17 18:00:50','2026-07-08 01:21:30'),(13,'刘鹗',8,1857,1909,'江苏丹徒（今江苏镇江）','字铁云，号老残，笔名鸿都百炼生。清末小说家、金石学家，江苏丹徒人。精算学、医学、水利，曾治黄河。因购太仓粟赈灾流放新疆，病逝迪化。著《老残游记》《铁云藏龟》。','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/poets/刘鹗_画像_01.jpg\"]',NULL,'谴责小说派','2026-06-17 18:00:50','2026-07-08 01:43:14'),(14,'张养浩',6,1270,1329,'济南路历城县（今山东济南历城区）','字希孟，号云庄，又称齐东野人。元代著名散曲家、政治家，唐名相张九龄弟张九皋二十三世孙。幼有才名，历官堂邑县尹、监察御史、礼部尚书、中书省参知政事。因朝政腐败辞官归隐济南云庄。天历二年关中大旱，出任陕西行台中丞救灾，到任四月积劳成疾卒于任上。代表作《山坡羊·潼关怀古》《云庄休居自适小乐府》。','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/poets/张养浩_画像_01.jpg\"]',NULL,'元散曲大家（清逸豪放）','2026-06-17 18:00:50','2026-07-08 01:21:30'),(15,'苏辙',5,1039,1112,'眉州眉山（今四川眉山）','字子由，一字同叔，晚号颍滨遗老。北宋文学家，唐宋八大家之一，与父苏洵、兄苏轼合称三苏。嘉祐二年与兄同登进士第。因反对王安石变法屡遭贬谪，又受乌台诗案牵连贬监筠州盐酒税。哲宗时官至门下侍郎。晚年居许州，谥文定。以散文著称，风格汪洋澹泊，擅长政论史论。著有《栾城集》。','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/poets/苏辙_画像_01.jpg\"]',NULL,'蜀学（唐宋八大家）','2026-06-17 18:00:50','2026-07-08 01:21:30'),(16,'李泂',6,1274,1332,'滕州（今山东滕州）','字溉之。元代文学家。因姚燧荐授翰林国史院编修，累官奎章阁承旨学士，参与修纂《经世大典》。书成引疾归，复以翰林直学士召不起。生有异禀，奋笔挥洒，纵横奇变，每以李白自拟。工散曲，著文集四十卷，列\"词林英杰\"。',NULL,NULL,'奎章阁文臣','2026-06-17 18:00:50','2026-07-08 01:43:13'),(17,'苏轼',5,1037,1101,'眉州眉山（今四川眉山）','字子瞻，号东坡居士，眉州眉山人，北宋中期文坛领袖，唐宋八大家之一。嘉祐二年进士，因\"乌台诗案\"贬黄州，晚年贬惠州、儋州。文、诗、词、书、画皆精，词开豪放一派，与辛弃疾并称\"苏辛\"，与黄庭坚并称\"苏黄\"。代表作有《念奴娇·赤壁怀古》《水调歌头》等。','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/poets/苏轼_画像_01.jpg\"]',NULL,'豪放派','2026-06-17 18:00:50','2026-07-08 01:21:30'),(18,'黄庭坚',5,1045,1105,'洪州分宁（今江西九江修水县）','字鲁直，号山谷道人，晚号涪翁，谥号文节。北宋诗人、书法家，江西诗派开山之祖，苏门四学士之首，与苏轼齐名世称苏黄，又为宋四家之一。治平四年进士，官至起居舍人。因党争屡遭贬谪，崇宁四年卒于宜州贬所。提出点铁成金、夺胎换骨诗法，影响深远。著有《山谷词》《豫章集》。','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/poets/黄庭坚_画像_01.jpg\"]',NULL,'江西诗派（开山之祖）','2026-06-17 18:00:50','2026-07-08 01:21:30'),(19,'阮元',8,1764,1849,'江苏扬州府仪征县（今江苏仪征）','字伯元，号芸台，又号雷塘庵主，清代学者、文学家，徽派朴学后期巨擘。乾隆五十四年进士，历乾嘉道三朝，官至体仁阁大学士，谥文达。诗取法中晚唐，清华婉丽；创诂经精舍、学海堂。著有《揅经室集》《畴人传》，主编《十三经注疏》《皇清经解》。','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/poets/阮元_画像_01.jpg\"]',NULL,'徽派朴学（扬州学派）','2026-06-17 18:00:50','2026-07-08 01:21:30'),(20,'浣花',8,NULL,NULL,'山东济南','《济游漫录》作者，号浣花，清代济南地方文人。',NULL,NULL,NULL,'2026-06-17 18:00:50','2026-07-01 20:35:28'),(21,'陆机',3,261,303,'吴郡吴县（今江苏苏州）','字士衡，西晋文学家、书法家，吴郡吴县人，为孙吴丞相陆逊之孙、大司马陆抗第四子，与弟陆云并称\"二陆\"。吴亡后入洛阳，文才倾动一时，受张华赏识，后卷入八王之乱，任后将军、河北大都督，兵败遭谗遇害，被夷三族。诗重藻绘排偶，与潘岳并称\"潘江陆海\"，为太康诗风代表。代表作有《文赋》《辩亡论》《平复帖》等。',NULL,NULL,'太康诗风（潘江陆海）','2026-06-17 18:00:50','2026-07-08 01:21:29'),(22,'谢道韫',3,NULL,NULL,'陈郡阳夏（今河南太康）','名韬元，字道韫，东晋女诗人，陈郡阳夏人，安西将军谢奕之女、宰相谢安侄女，嫁王羲之之子王凝之。聪慧博学，因\"未若柳絮因风起\"被誉为\"咏絮之才\"，神情散朗，有林下之风。孙恩之乱中丈夫及子女遇害，她持刀杀贼被俘，后寡居会稽终老。诗风清逸玄远、格调疏朗。代表作有《泰山吟》《拟嵇中散咏松诗》《论语赞》等。',NULL,NULL,'玄言诗（林下风气）','2026-06-17 18:00:50','2026-07-08 01:21:29'),(23,'石介',5,1005,1045,'兖州奉符（今山东泰安）','字守道，一字公操，号徂徕先生，北宋兖州奉符人。天圣八年进士，历任郓州推官、国子监直讲，创建泰山、徂徕书院，与胡瑗、孙复并称\"宋初三先生\"，开宋明理学之先声。作《庆历圣德颂》拥护新政遭夏竦陷害，庆历五年卒，著有《徂徕集》。',NULL,NULL,'泰山学派（理学先驱）','2026-06-17 18:00:50','2026-07-08 01:43:13'),(24,'宋濂',7,1310,1381,'金华浦江（今浙江浦江）','字景濂，号潜溪，元末明初浦江人，文学家、史学家。明初受朱元璋礼聘，为太子师，主修《元史》，官至翰林学士承旨，被誉为\"开国文臣之首\"。与高启、刘基并称\"明初诗文三大家\"。洪武十年辞官，后因长孙牵连胡惟庸案流放茂州，途中病逝夔州，谥文宪。代表作《送东阳马生序》《宋学士文集》。',NULL,NULL,'台阁体','2026-06-17 18:00:50','2026-07-08 01:21:30'),(25,'方孝孺',7,1357,1402,'浙江台州府宁海县（今浙江宁海）','字希直，一字希古，号逊志，又称\"正学先生\"，明朝初期大臣、文学家、思想家。师从宋濂，建文帝时官翰林学士。靖难之役后拒不草拟朱棣即位诏书，被凌迟处死。文章醇深雄迈、纵横豪放，著有《逊志斋集》《深虑论》。',NULL,NULL,'浙东理学派（醇深雄迈）','2026-06-17 18:00:50','2026-07-08 01:21:30'),(26,'徐文通',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(27,'李攀龙',7,1514,1570,'山东济南府历城（今山东济南）','字于鳞，号沧溟。明代著名文学家，\"后七子\"领袖人物。嘉靖二十三年进士，历官刑部主事、顺德知府、陕西提学副使、河南按察使。继\"前七子\"倡导文学复古运动，主盟文坛二十余年，长于七言近体。著《沧溟集》。',NULL,NULL,'后七子领袖，文学复古派','2026-06-17 18:00:50','2026-07-08 01:43:13'),(28,'徐中行',7,1517,1578,'浙江长兴（今浙江湖州）','字子舆，号龙湾，又号天目山人。明代文学家，\"后七子\"之一。嘉靖二十九年进士，历官汀州知府、云南参议、福建按察使、江西左布政使。因探视杨继盛被贬，诗多描绘各地山川风貌。著《天目山堂集》《青萝馆诗》。',NULL,NULL,'后七子之一，善七律','2026-06-17 18:00:50','2026-07-08 01:43:13'),(29,'李化龙',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(30,'李中行',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(31,'蒲松龄',8,1640,1715,'山东淄川（今山东淄博淄川区）','字留仙，一字剑臣，号柳泉居士，世称聊斋先生，山东淄川人，清代文学家、小说家。19岁连中县府道第一，此后屡试不第，71岁始成贡生。一生以坐馆教书为业。著文言短篇小说集《聊斋志异》，被誉为\"世界短篇小说之王\"。',NULL,NULL,'文言小说（雅俗结合，借鬼狐讽世）','2026-06-17 18:00:50','2026-07-08 01:21:30'),(32,'赵执信',8,1662,1744,'山东益都（今山东淄博博山）','字伸符，号秋谷，晚号饴山老人。清初诗人、诗论家，山东益都人。十八岁中进士，任右春坊右赞善。因\"长生殿案\"革职，终身不仕。为王士禛甥婿，论诗异趣，主\"文意为主\"。著《饴山诗集》《谈龙录》。',NULL,NULL,'现实诗派','2026-06-17 18:00:50','2026-07-08 01:43:14'),(33,'魏源',8,1794,1857,'湖南邵阳金潭（今湖南隆回）','名远达，字默深，又字墨生、汉士，号良图，清代启蒙思想家、文学家。道光二十五年进士，官高邮知州。与龚自珍并称\"龚魏\"，倡\"师夷长技以制夷\"，开近代向西方学习之先声。晚年信佛，法名承贯。著有《海国图志》《圣武记》《古微堂集》。',NULL,NULL,'今文学派（经世致用派）','2026-06-17 18:00:50','2026-07-08 01:21:30'),(34,'刘长卿',4,NULL,NULL,'宣州宣城（今安徽宣城），郡望河间（今河北献县）','字文房，中唐大历诗风代表诗人。宣州宣城人，后迁洛阳。天宝间进士及第，两度遭贬谪，官终随州刺史，世称刘随州。工五言，自称\"五言长城\"，与钱起并称\"钱刘\"。代表作《逢雪宿芙蓉山主人》《送灵澈上人》《长沙过贾谊宅》。',NULL,NULL,'大历诗风代表，五言长城','2026-06-17 18:00:50','2026-07-08 01:43:12'),(35,'袁桷',6,1266,1327,'庆元路鄞县（今浙江宁波）','字伯长，号清容居士。元代学官、文学家。庆元鄞县人，师事戴表元、王应麟。大德初荐授翰林国史院检阅官，官至侍讲学士，参与修撰宋辽金三史，朝廷制册勋臣碑铭多出其手。卒谥文清。著《清容居士集》《延祐四明志》。',NULL,NULL,'元代浙东文派','2026-06-17 18:00:50','2026-07-08 01:43:13'),(36,'吴师道',6,1283,1344,'婺州兰溪（今浙江兰溪）','字正传。元代婺州兰溪人。至治元年进士，授高邮县丞，主持兴筑漕渠，官至国子博士、礼部郎中。以道学自任，晚年益精于学，剖析精严。诗文清丽，著《战国策校注》《礼部集》二十卷、《敬乡录》。',NULL,NULL,'金华理学派','2026-06-17 18:00:50','2026-07-08 01:43:13'),(37,'萨都剌',6,NULL,NULL,'代州雁门（今山西代县）','字天锡，号直斋，回回人，先世为西域人。元代著名诗人、画家，人称\"雁门才子\"。泰定四年进士，历官镇江路录事司达鲁花赤、江南行御史台掾史、燕南河北道肃政廉访司经历等，宦游南北。为官清廉，晚年寓居杭州。诗风清丽俊逸，词作豪迈奔放，后人誉为\"有元一代词人之冠\"。代表作《雁门集》《满江红·金陵怀古》。',NULL,NULL,'清丽俊逸（元代词人之冠）','2026-06-17 18:00:50','2026-07-08 01:21:30'),(39,'胡广',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(40,'徐祯卿',7,1479,1511,'常熟梅李镇，徙居吴县（今江苏苏州）','字昌谷，一字昌国，明代文学家，\"吴中四才子\"与\"前七子\"之一。弘治十八年进士，因貌丑不得入翰林，官至国子监博士。论诗主情致，风格清朗、熔炼精警，誉为\"吴中诗冠\"，享寿仅三十三岁。著有《迪功集》《谈艺录》。',NULL,NULL,'前七子复古派（吴中诗派）','2026-06-17 18:00:50','2026-07-08 01:21:30'),(41,'王世贞',7,1526,1590,'南直隶苏州府太仓州（今江苏太仓）','字元美，号凤洲，又号弇州山人，明代文学家、史学家，\"后七子\"领袖。嘉靖二十六年进士，官至南京刑部尚书，卒赠太子少保。李攀龙死后独主文坛二十年，主张\"文必秦汉、诗必盛唐\"。著有《弇州山人四部稿》《艺苑卮言》。','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/poets/王士贞_作者_01.jpg\"]',NULL,'后七子复古派','2026-06-17 18:00:50','2026-07-08 01:21:30'),(42,'高出',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(43,'秦松龄',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(44,'爱新觉罗·玄烨',8,1654,1722,'北京紫禁城','清圣祖，爱新觉罗·玄烨，年号康熙，庙号圣祖。清朝第四位皇帝，在位六十一年，为历史上在位最久者。生于北京紫禁城景仁宫。文武兼备，勤于学问，六经要旨无不贯通。留存诗作千余首，多记巡幸、政务、山川，诗风雅正质朴。开博学鸿词科，笼络汉族士人，奠定康乾盛世根基。',NULL,NULL,'御制诗','2026-06-17 18:00:50','2026-07-08 01:43:14'),(45,'卢见曾',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(46,'田致',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(47,'爱新觉罗·弘历',8,1711,1799,'北京（雍亲王府）','清高宗，爱新觉罗·弘历，年号乾隆，庙号高宗。清朝第六位皇帝，在位六十年。生于北京雍亲王府。一生作诗逾四万三千首，为历史上最多产诗人，自言\"或出词臣之手，真赝各半\"。主张诗以言志、贵有神韵，诗风写实而乏韵。著有《御制诗》五集及《乐善堂全集》。',NULL,NULL,'御制诗','2026-06-17 18:00:50','2026-07-08 01:43:14'),(49,'许朝',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(50,'李浃',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(51,'曹操',2,155,220,'沛国谯县（今安徽亳州）','字孟德，小字阿瞒，沛国谯县人，东汉末年杰出的政治家、军事家、文学家、书法家，三国曹魏政权的奠基人。统一中国北方，奠定曹魏立国基础。与子曹丕、曹植并称\"三曹\"，开创建安文学。代表作有《观沧海》《短歌行》《龟虽寿》等。',NULL,NULL,'建安风骨（慷慨悲凉）','2026-06-17 18:00:50','2026-07-08 01:21:29'),(52,'晁补之',5,1053,1110,'济州巨野（今山东巨野）','字无咎，号归来子，北宋济州巨野人，苏门四学士之一。曾任吏部员外郎、礼部郎中，工书画、能诗词，与张耒并称\"晁张\"。散文凝练流畅近柳宗元，诗学陶渊明，词格调豪爽近苏轼，著有《鸡肋集》《晁氏琴趣外篇》。',NULL,NULL,'苏门四学士','2026-06-17 18:00:50','2026-07-08 01:43:13'),(53,'许景衡',5,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(54,'陶安',7,1315,1368,'太平府当涂（今安徽当涂）','字主敬。元末明初文人。元至正举人，授明道书院山长。朱元璋渡江时迎谒献策，授左司员外郎，后任左司郎中。洪武元年任知制诰兼修国史，出任江西行省参知政事，卒于官。著《陶学士集》。',NULL,NULL,'元末明初文人，明初开国文臣','2026-06-17 18:00:50','2026-07-08 01:43:13'),(55,'杨巍',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(56,'谢榛',7,1495,1575,'山东临清（今山东临清）','字茂秦，号四溟山人、脱屣山人。明代布衣诗人，\"后七子\"之一。一目失明，终生布衣不求仕进。与李攀龙、王世贞结诗社，后被排斥，客游诸藩王间。善律绝，句响字稳。著《四溟集》《四溟诗话》。',NULL,NULL,'后七子之一，布衣诗人','2026-06-17 18:00:50','2026-07-08 01:43:13'),(57,'杨玉润',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(58,'王象春',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(59,'汪琬',8,1624,1691,'长洲（今江苏苏州）','字苕文，号钝翁，晚号尧峰。清初散文家，长洲（今江苏苏州）人。顺治十二年进士，历官户部主事、刑部郎中；康熙十八年举博学鸿词，授翰林院编修，预修《明史》。晚年隐居太湖尧峰山，闭户著述。与侯方域、魏禧并称清初散文三大家，文风简洁平实、疏畅条达，亦能诗，以清丽为宗。著有《尧峰诗文钞》。',NULL,NULL,'清初散文三大家（唐宋派）','2026-06-17 18:00:50','2026-07-08 01:43:14'),(60,'张衍',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(61,'沈廷芳',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(62,'严文典',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(63,'张衍重',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(64,'沈世铨',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(65,'李隆基',4,685,762,'东都洛阳（今河南洛阳）','即唐玄宗，亦称唐明皇，712至756年在位。前期开创开元盛世，后期宠杨贵妃，重用李林甫、杨国忠，引发安史之乱。生性英明果断，知晓音律，仪表雄伟，工诗能文。代表作《端午三殿宴群臣探得神字》《千秋节宴》。','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/poets/李隆基_作者_01.jpg\"]',NULL,'帝王诗，盛唐气象','2026-06-17 18:00:50','2026-07-08 01:43:12'),(66,'陈凤梧',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(67,'薛瑄',7,1389,1464,'山西河津（今山西万荣）','字德温，号敬轩。明代政治家、理学家，河东学派创始人。永乐十九年进士，官至礼部左侍郎兼翰林院学士。为官清廉刚直，创立\"复性说\"，致仕后聚徒讲学，隆庆五年从祀孔庙。著《读书录》《读书续录》。',NULL,NULL,'河东学派创始人','2026-06-17 18:00:50','2026-07-08 01:43:13'),(69,'戴璟',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(70,'胤禛',8,1678,1735,'北京紫禁城','清世宗，爱新觉罗·胤禛，年号雍正，庙号世宗，自号破尘居士、圆明主人。清朝第五位皇帝。生于北京紫禁城永和宫。在位十三年，勤于政事，推行摊丁入亩、火耗归公、改土归流等改革。著有《雍邸集》《四宜堂集》诗五百余首，诗风清雅，多咏读书、园居之作。',NULL,NULL,'御制诗','2026-06-17 18:00:50','2026-07-08 01:43:14'),(71,'顾炎武',8,1613,1682,'南直隶昆山（今江苏昆山）','原名绛，字忠清，明亡后改名炎武，号亭林。明末清初杰出的思想家、史学家、语言学家，与黄宗羲、王夫之并称明末清初三大儒。顺治年间曾游历山东，在曲阜谒孔庙，登泰山赋诗。','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/poets/顾炎武_作者_01.jpg\"]',NULL,NULL,'2026-06-17 18:00:50','2026-07-01 20:35:28'),(72,'郭沫若',8,1892,1978,'四川乐山','原名郭开贞，字鼎堂，号尚武，中国现代文学家、历史学家、考古学家。曾访曲阜孔庙并题诗。','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/poets/郭沫若_作者_01.jpg\"]',NULL,NULL,'2026-06-17 18:00:50','2026-07-01 20:35:28'),(73,'罗隐',4,833,909,'新城（今浙江杭州富阳）','本名横，字昭谏，自号江东生。晚唐五代诗人、文学家。寒儒出身，十举进士不第，遂改名隐。后归吴越王钱镠，历任钱塘令、给事中。诗文多讥刺时政，长于咏史，鲁迅评其《谗书》为抗争愤激之谈。代表作《蜂》《自遣》《西施》《雪》。',NULL,NULL,'晚唐讽刺小品，咏史派','2026-06-17 18:00:50','2026-07-08 01:43:12'),(74,'蒙建华',8,NULL,NULL,'山东济宁','当代诗人，济宁人，著有咏任城诗作。',NULL,NULL,NULL,'2026-06-17 18:00:50','2026-07-01 20:35:28'),(75,'郑守生',8,NULL,NULL,'山东济宁','当代诗人，济宁人，擅写运河题材诗作。',NULL,NULL,NULL,'2026-06-17 18:00:50','2026-07-01 20:35:28'),(76,'李如圭',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(77,'龚勉',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(78,'杭世骏',8,NULL,NULL,'仁和（今浙江杭州）','字大宗，号堇浦，晚年自号秦亭老民。清代学者、诗人，浙江仁和（今杭州）人。雍正举人，乾隆元年举博学鸿词科，授翰林编修，因上书言\"满汉畛域\"触怒乾隆，革职归里，主讲扬州、粤东书院。诗与厉鹗齐名，为浙派代表，诗风平淡中见豪放。著有《道古堂集》。',NULL,NULL,'浙派','2026-06-17 18:00:50','2026-07-08 01:43:14'),(79,'徐金铭',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(80,'殷云宵',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(81,'刘晏',4,716,780,'曹州南华（今山东菏泽东明）','字士安，中唐经济改革家、理财家。曹州南华人。七岁举神童，献颂授太子正字。官至吏部尚书同平章事，改革漕运、盐政、常平法，使唐财政收入由六十万贯增至千万贯，代宗誉之可比萧何。后被杨炎陷害赐死。存诗二首，代表作《咏王大娘戴卒》。',NULL,NULL,'经济改革家（非以诗名）','2026-06-17 18:00:50','2026-07-08 01:43:12'),(82,'胡曾',4,NULL,NULL,'邵州邵阳（今湖南邵阳）','字号不详，晚唐诗人。邵州邵阳人，早年寓居长沙。咸通中举进士不第，后入路岩、高骈幕府为掌书记。工诗长律绝，著《咏史诗》一百五十首皆七绝，以地名为题，托古讽今，通俗浅显，为现存唐人咏史组诗之最。代表作《咏史诗·赤壁》《咏史诗·南阳》。',NULL,NULL,'晚唐咏史组诗大家','2026-06-17 18:00:50','2026-07-08 01:43:12'),(83,'杨亿',5,974,1020,'建州浦城（今福建浦城）','字大年，北宋建州浦城人，西昆体诗歌主要作家。七岁能文，十一岁受太宗赏识授秘书省正字，淳化中赐进士，官至工部侍郎、翰林学士。性耿介尚气节，参预修《太宗实录》、主修《册府元龟》，与同僚唱和编《西昆酬唱集》开西昆诗派，著有《武夷新集》。',NULL,NULL,'西昆体','2026-06-17 18:00:50','2026-07-08 01:43:13'),(84,'裴迪',4,716,NULL,'河东（今山西）','字不详，唐代诗人，河东人。官蜀州刺史及尚书省郎，盛唐著名山水田园诗人之一。与王维、杜甫关系密切，晚年居辋川、终南山，诗多与王维唱和应酬之作。受王维影响，诗大多为五绝，描写幽寂景色，风格与王维山水诗相近。代表作《辋川集二十首》《送崔九》。',NULL,NULL,'山水田园诗派','2026-06-17 18:00:50','2026-07-08 01:43:12'),(85,'李好文',6,NULL,NULL,'大名路东明（今山东东明）','字惟中，号河滨渔者、葵邱山人。元代大名路东明人。至治元年进士，历官国子祭酒、礼部尚书、翰林学士承旨，参与纂修辽金宋三史，曾为太子师，编《端本堂经训要义》。编《长安志图》《太常集礼》《大宝龟鉴》。',NULL,NULL,'馆阁文臣','2026-06-17 18:00:50','2026-07-08 01:43:13'),(86,'何景明',7,1483,1521,'河南信阳','字仲默，号白坡，又号大复山人。明代文学家，\"前七子\"领袖之一。弘治十五年进士，授中书舍人，官至陕西提学副使。与李梦阳并称，主张\"文必秦汉，诗必盛唐\"，倡导文学复古。著《大复集》。',NULL,NULL,'前七子领袖，文必秦汉诗必盛唐','2026-06-17 18:00:50','2026-07-08 01:43:13'),(87,'陈其猷',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(88,'石星',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(89,'李先芳',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(90,'杨应标',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(91,'范通',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(92,'韩翃',4,729,788,'南阳（今河南南阳）','字君平，中唐诗人，大历十才子之一。南阳人。天宝十三载进士及第，辗转淄青、汴宋等藩镇幕府。建中初因《寒食》诗受德宗赏识，御笔擢驾部郎中、知制诰，终中书舍人。诗多送别酬赠写景，笔法轻巧别致。代表作《寒食》《宿石邑山中》《章台柳·寄柳氏》。',NULL,NULL,'大历十才子，清空闲雅','2026-06-17 18:00:50','2026-07-08 01:43:12'),(93,'韩愈',4,768,824,'河南河阳（今河南孟州）','字退之，世称韩昌黎，河南河阳人，唐代文学家、思想家，唐宋八大家之首，古文运动倡导者。三岁而孤，贞元八年登进士第，官至吏部侍郎。因谏迎佛骨被贬潮州刺史。倡导\"文以载道\"，反对骈偶绮靡文风，文章质朴雄健。诗与孟郊并称\"韩孟\"，力求新奇。代表作有《师说》《进学解》《祭十二郎文》等。',NULL,NULL,'古文运动（奇崛雄健）','2026-06-17 18:00:50','2026-07-08 01:21:29'),(94,'文天祥',5,1236,1283,'江南西路吉州庐陵县（今江西吉安）','字宋瑞，又字履善，号文山、浮休道人。南宋末年政治家、文学家、民族英雄，与陆秀夫、张世杰并称\"宋末三杰\"。宝祐四年状元及第，官至右丞相兼枢密使。元军南下，散尽家财勤王抗元，兵败被俘，囚禁三年誓死不屈，从容就义。代表作《过零丁洋》《正气歌》。',NULL,NULL,'南宋爱国诗派（慷慨悲壮）','2026-06-17 18:00:50','2026-07-08 01:21:30'),(95,'宋褧',6,1294,1346,'大都宛平（今北京）','字显夫。元代大都宛平人。泰定元年进士，授秘书监校书郎，改翰林编修，历官监察御史、国子司业、翰林直学士兼经筵讲官。与兄宋本（字诚夫）先后登第，时人荣之。卒赠范阳郡侯，谥文清。著《燕石集》。',NULL,NULL,'元代馆阁体','2026-06-17 18:00:50','2026-07-08 01:43:13'),(96,'乃贤',6,1309,1368,'葛逻禄部人，后迁庆元（今浙江宁波）','字易之，号河朔外史、紫云山人。元代色目葛逻禄部诗人。祖上随蒙古军入中原，先居南阳，后迁庆元。淡泊名利，至正间任翰林国史院编修。近体清丽妥适，古诗直面现实，有\"诗史\"之称，与韩与玉、王子充并称\"江南三绝\"。著《金台集》《河朔访古记》。',NULL,NULL,'元末色目诗人','2026-06-17 18:00:50','2026-07-08 01:43:13'),(97,'唐之淳',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(98,'侯祁',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(99,'陈良谟',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(100,'张锷',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(101,'李洞',4,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(102,'张咏',5,946,1015,'濮州鄄城（今山东菏泽鄄城）','字复之，自号乖崖，北宋濮州鄄城人。太平兴国五年进士，历任枢密直学士、两知益州，政绩显著，参与平定王小波李顺起义，官至礼部尚书。为政尚严猛，与寇准交好，后世称为\"交子之父\"，诗文豪劲有气骨，著有《乖崖集》。',NULL,NULL,'北宋诗文革新先驱','2026-06-17 18:00:50','2026-07-08 01:43:13'),(103,'关汉卿',6,NULL,NULL,'解州（今山西运城）','字汉卿，号已斋（一作一斋、已斋叟），元代杂剧奠基人，元曲四大家之首，誉为\"曲圣\"。籍贯有解州、大都、祁州等多说，中年定居大都，主持玉京书会，晚年南下游历，终老祁州。一生创作杂剧六十余种，现存十八种，代表作《窦娥冤》《救风尘》《拜月亭》《望江亭》等，深刻揭露元代社会黑暗。',NULL,NULL,'元曲四大家','2026-06-17 18:00:50','2026-07-08 01:21:30'),(104,'佚名',7,NULL,NULL,NULL,'佚名，无作者可考。',NULL,NULL,NULL,'2026-06-17 18:00:50','2026-07-08 01:21:06'),(105,'高适',4,NULL,765,'渤海蓨县（今河北景县）','字达夫，一字仲武，盛唐边塞诗派领军人物。早年家贫，客游梁宋。三次出塞，创作大量边塞诗。安史之乱后官至淮南、剑南节度使，封渤海县侯，世称高常侍。与岑参并称高岑，与王之涣、王昌龄、岑参合称边塞四诗人。代表作《燕歌行》《别董大》。',NULL,NULL,'边塞诗派','2026-06-17 18:00:50','2026-07-08 01:21:30'),(106,'萧楚材',4,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(107,'林逋',5,967,1028,'钱塘（今浙江杭州）','字君复，谥和靖先生，北宋著名隐逸诗人。早年游历江淮，后隐居杭州西湖孤山二十年，终身不仕不娶，以梅鹤为伴，世称梅妻鹤子。性孤高，不趋荣利。诗多写西湖景色与隐逸生活，风格澄澹高远。代表作《山园小梅》\"疏影横斜水清浅，暗香浮动月黄昏\"，被誉为千古咏梅绝唱。著有《林和靖先生诗集》。',NULL,NULL,'隐逸诗派（晚唐体）','2026-06-17 18:00:50','2026-07-08 01:21:30'),(108,'陈师道',5,1053,1102,'彭城（今江苏徐州）','字履常，一字无己，号后山居士，北宋彭城人，苏门六君子之一，江西诗派重要作家。元祐初苏轼荐为徐州教授，历太学博士、颍州教授、秘书省正字。一生安贫乐道、闭门苦吟，有\"闭门觅句陈无己\"之称，诗学杜甫以拗峭惊警见长，著有《后山先生集》《后山词》。',NULL,NULL,'江西诗派（苏门六君子）','2026-06-17 18:00:50','2026-07-08 01:43:13'),(109,'王恽',6,1227,1304,'卫州路汲县（今河南卫辉）','字仲谋，号秋涧。元代学者、诗人兼政治家。卫州汲县人，历仕世祖、裕宗、成宗三朝，官至翰林学士，刚直不阿，清贫守职。诗风清新典雅，温醇雍容，平淡蕴藉。著《秋涧先生大全集》，存诗五百余首、散曲小令四十一首。',NULL,NULL,'元初馆阁诗文','2026-06-17 18:00:50','2026-07-08 01:43:13'),(110,'何应瑞',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(111,'王曰高',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(112,'刘大绅',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(113,'李商隐',4,813,858,'怀州河内（今河南沁阳）','字义山，号玉谿生、樊南生，祖籍怀州河内，生于河南荥阳，晚唐诗人，与杜牧合称\"小李杜\"，与温庭筠并称\"温李\"。早年丧父，开成二年进士及第，因娶王茂元之女卷入牛李党争，仕途坎坷，终身不得志。诗风朦胧幽深、深情绵邈，工于比兴善用典故，开创无题诗，自成\"义山体\"。代表作有《锦瑟》《无题·相见时难别亦难》《夜雨寄北》等。',NULL,NULL,'晚唐朦胧诗（义山体）','2026-06-17 18:00:50','2026-07-08 01:21:29'),(114,'元稹',4,779,831,'河南府洛阳（今河南洛阳）','字微之，别字威明，河南洛阳人，唐代文学家，北魏宗室鲜卑拓跋部后裔。八岁丧父，贞元九年明经及第，与白居易同科结为终生诗友，共同倡导新乐府运动，世称\"元白\"，形成\"元和体\"。一度拜相，后被贬外任，终任武昌军节度使。诗风言浅意哀，动人肺腑，擅写悼亡诗与爱情诗。代表作有传奇《莺莺传》《离思五首》《遣悲怀三首》等。',NULL,NULL,'新乐府运动（元和体）','2026-06-17 18:00:50','2026-07-08 01:21:29'),(115,'王冕',6,1287,1359,'诸暨（今浙江诸暨）','字元章，号煮石山农、梅花屋主、会稽外史，元末诸暨人，画家、诗人、篆刻家。出身贫寒，幼年放牛自学成才，师从韩性。屡试不第，遂隐居会稽九里山，种梅画梅以卖画为生。性格孤傲，鄙视权贵，朱元璋请为官，以出家拒之。代表作《墨梅图》《南枝春早图》《竹斋集》，诗画兼擅，人称\"画梅圣手\"。',NULL,NULL,'元末隐逸诗派','2026-06-17 18:00:50','2026-07-08 01:21:30'),(116,'杨维桢',6,1296,1370,'会稽诸暨（今浙江绍兴诸暨）','字廉夫，号铁崖、东维子、铁笛道人，元末会稽诸暨人，文学家、书画家。泰定四年进士，任天台县尹，后官至建德路推官、江西儒学提举。元末兵乱避居富春山，晚年寓居松江。以古乐府诗擅名，独创\"铁崖体\"，在元季文坛独领风骚四十余年，与陆居仁、钱惟善并称\"元末三高士\"。代表作《铁崖古乐府》《东维子集》。',NULL,NULL,'铁崖体','2026-06-17 18:00:50','2026-07-08 01:21:30'),(117,'张问陶',8,1764,1814,'四川遂宁（今四川遂宁蓬溪）','字仲冶，号船山，清代中叶杰出诗人、书画家。四川遂宁人，乾隆进士，官翰林院检讨、莱州知府。与袁枚、赵翼并称\"性灵派三大家\"，誉为\"蜀中诗人之冠\"。代表作《船山诗草》。',NULL,NULL,'性灵派','2026-06-17 18:00:50','2026-07-08 01:43:13'),(118,'刘克庄',5,1187,1269,'兴化军莆田（今福建莆田）','初名灼，字潜夫，号后村居士，南宋诗人、词人、诗论家。师事真德秀。因《落梅》诗案闲废十年。官至龙图阁学士，权工部尚书。诗属江湖诗派，成就为该派之冠；词受辛弃疾影响，为辛派词人三刘之一。宋末文坛领袖，谥文定。亦是最早的《千家诗》编选者。著有《后村先生大全集》《后村长短句》。',NULL,NULL,'江湖诗派（词属辛派）','2026-06-17 18:00:50','2026-07-08 01:21:30'),(119,'吴铠',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(120,'陈廷敬',8,1638,1712,'山西泽州府阳城（今山西晋城阳城）','字子端，号说岩、午亭。清康熙朝名臣、诗人，山西阳城人。顺治进士，官至文渊阁大学士，辅佐康熙逾半个世纪。总裁《康熙字典》《明史》，著《午亭文编》《尊闻堂集》。',NULL,NULL,NULL,'2026-06-17 18:00:50','2026-07-08 01:43:13'),(121,'陈仁德',8,NULL,NULL,'四川重庆','近代诗人，曾游历山东阳谷县，留有咏景阳冈、狮子楼等名胜诗篇。',NULL,NULL,NULL,'2026-06-17 18:00:50','2026-07-01 20:35:28'),(122,'王士禛',8,1634,1711,'山东新城（今山东淄博桓台）','字子真，号阮亭，别号渔洋山人。清初诗坛领袖，山东新城人，顺治进士，官至刑部尚书。创\"神韵说\"，与朱彝尊并称\"南朱北王\"，领袖文坛五十余年。代表作《渔洋诗集》《池北偶谈》。',NULL,NULL,'神韵说','2026-06-17 18:00:50','2026-07-08 01:43:13'),(123,'于钦',6,1283,1333,'益都（今山东青州）','字思容，号敬止。元代方志编纂家、历史地理学家、文学家。祖籍文登，生于益都。历官山东廉访司照磨、兵部侍郎、益都田赋总管，任内赈济饥民、赎回鬻儿。精于方志，著《齐乘》六卷，为山东现存最早方志，纪晓岚评其\"叙述简核而淹贯\"。',NULL,NULL,'元代方志学派','2026-06-17 18:00:50','2026-07-08 01:43:13'),(124,'章忠',7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(125,'刘学渤',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(126,'张本大',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(127,'汤朝槭',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(128,'狄培',8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-17 18:00:50','2026-06-17 18:00:50'),(129,'施闰章',8,1619,1683,'江南宁国府宣城（今安徽宣城）','字尚白，号愚山，又号蠖斋。清初著名诗人，安徽宣城人。顺治进士，官至翰林侍读，预修《明史》。与宋琬并称\"南施北宋\"，擅五言诗，创\"宣城体\"。代表作《学余堂诗集》。',NULL,NULL,'宣城体','2026-06-17 18:00:50','2026-07-08 01:43:14'),(130,'金天羽',8,1874,1947,'江苏吴江','原名金天翮，字松岑，号天放楼主人。清末民初学者、诗人，曾游历济宁。',NULL,NULL,NULL,'2026-06-17 18:00:50','2026-07-01 20:35:28');
/*!40000 ALTER TABLE `poet` ENABLE KEYS */;
