INSERT INTO `scenic_spot` VALUES (1,'大明湖','始建于北魏，历代重修扩建；杜甫、李邕曾游宴，有\"济南名士多\"典故',117.0158330,36.6700000,'大明湖景区历下亭','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/历下亭_实景_01.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/大明湖_实景_01.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/超然楼_实景_01.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/铁公祠_实景_01.jpg\"]','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/历下亭_实景_01.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/大明湖_实景_01.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/超然楼_实景_01.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/铁公祠_实景_01.jpg\"]','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/video/历下亭_视频_01.mp4\"]','济南','2026-06-17 18:00:50','2026-07-01 20:45:52'),(2,'趵突泉','始建于北魏，宋代始建亭，历代重修；乾隆御封\"天下第一泉\"，为济南三大名胜之一',117.0116670,36.6630560,'趵突泉景区观澜亭','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/趵突泉_实景_06.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/趵突泉_实景_01.jpg\"]','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/趵突泉_实景_01.jpg\"]','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/video/趵突泉_视频_01.mp4\"]','济南','2026-06-17 18:00:50','2026-07-20 18:52:33'),(3,'千佛山','古称历山，隋代凿佛建寺，历代扩建；佛教名山，济南三大名胜之一，有舜耕传说',117.0083330,36.6433330,'千佛山风景名胜区','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/千佛山_实景_01.jpg\"]','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/千佛山_实景_01.jpg\"]',NULL,'济南','2026-06-17 18:00:50','2026-07-01 20:45:52'),(4,'华不注山','春秋已得名，为古济南名山；孤峰刺天，历代画家诗人题咏众多，赵孟頫《鹊华秋色》主角之一',117.0866670,36.7366670,'黄河南岸华山森林公园','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/华不注_实景_01.jpg\"]','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/华不注_实景_01.jpg\"]',NULL,'济南','2026-06-17 18:00:50','2026-07-01 20:45:53'),(5,'鹊山','因扁鹊炼丹传说得名，为济南名山；与华不注并称鹊华，为赵孟頫《鹊华秋色》主角之一',117.0166670,36.7500000,'黄河北岸鹊山村','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/鹊山_实景_01.jpg\"]','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/鹊山_实景_01.jpg\"]','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/video/鹊山_视频_01.mp4\"]','济南','2026-06-17 18:00:50','2026-07-01 20:45:53'),(6,'汇波楼','始建于元代，历代重修；汇波晚照为济南八景之一',117.0180560,36.6722220,'大明湖景区汇波楼','https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/汇波楼_实景_01.jpg','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/汇波楼_实景_01.jpg\"]','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/video/大明湖_汇波楼_视频_01.mp4\"]','济南','2026-06-17 18:00:50','2026-07-01 20:45:53'),(7,'五龙潭','隋唐已成名泉，历代修整；传说为秦琼故居，泉群汇为深潭',117.0138890,36.6658330,'五龙潭公园','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/五龙潭_实景_01.jpg\"]','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/五龙潭_实景_01.jpg\"]',NULL,'济南','2026-06-17 18:00:50','2026-07-01 20:45:53'),(8,'珍珠泉','金代已列入名泉志，明清为巡抚衙门驻地；泉沸如浮珍珠，为济南四大名泉之一',117.0166670,36.6669440,'珍珠泉大院','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/珍珠泉_实景_01.jpg\"]','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/珍珠泉_实景_01.jpg\"]','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/video/珍珠泉_视频_01.mp4\"]','济南','2026-06-17 18:00:50','2026-07-01 20:45:53'),(9,'黑虎泉','金代已列入名泉，明代始建石龛；三兽喷黑水，声如虎啸，为济南四大名泉之一',117.0208330,36.6597220,'黑虎泉泉群','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黑虎泉_实景_01.jpg\"]','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黑虎泉_实景_01.jpg\"]',NULL,'济南','2026-06-17 18:00:50','2026-07-01 20:45:53'),(10,'华山','古称华不注，春秋齐晋鞌之战发生于此；孤峰独秀，为济南胜景',117.0866670,36.7366670,'华不注山','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/华不注_实景_01.jpg\"]','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/华不注_实景_01.jpg\"]',NULL,'济南','2026-06-17 18:00:50','2026-07-01 20:45:53'),(11,'金线泉','金代已列入名泉志，清代归并入趵突泉公园；水面有纹如金线，为济南四大名泉之一',117.0122220,36.6627780,'趵突泉公园内','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/金线泉_实景_01.jpg\"]','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/金线泉_实景_01.jpg\"]','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/video/金线泉_视频_01.mp4\"]','济南','2026-06-17 18:00:50','2026-07-01 20:45:53'),(12,'灵岩寺','始建于东晋，唐代拓建，历代重修；海内四大名刹之首，有千佛殿辟支塔',116.9666670,36.3666670,'泰山西北灵岩寺景区','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/灵岩寺_实景_01.jpg\"]','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/灵岩寺_实景_01.jpg\"]','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/video/灵岩寺_视频_01.mp4\"]','济南','2026-06-17 18:00:50','2026-07-01 20:45:53'),(13,'龙洞','北魏已见记载，为济南东名山；山川幽胜，有龙洞秋风为济南八景之一',117.1166670,36.6833330,'龙洞风景区','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/龙洞_实景_01.jpg\"]','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/龙洞_实景_01.jpg\"]',NULL,'济南','2026-06-17 18:00:50','2026-07-01 20:45:53'),(14,'泰山','先秦至秦汉：先秦时期已成为五岳之首和政权象征，秦始皇统一六国后，将泰山祭祀仪式变为帝王专有的封禅大典。汉武帝曾先后8次前往岱顶封禅，汉光武帝也进行过一次泰山封禅。\n魏晋南北朝：佛教和道教相继流入泰山，时局动荡使常规祭祀难以开展，临时的非常规祭祀盛行，分裂政权常祭祀泰山以证明统治合法性。\n隋唐宋金：隋代开创泰山祭祀制度，将其纳入政府行政体系；唐代开创泰山封爵制度，并规范祭祀仪式程序。宋代宋真宗前往泰山封禅，此后皇帝不再正式举办封禅大典。金代泰山庙呈现道教化宫观化色彩。这一时期还出现了泰山书院。\n元明清：元代加封泰山为“东岳为天齐大生仁圣帝”；明朝增设管理泰山的官员，文人墨客游览增多并留下墨迹；清朝康熙、乾隆等皇帝都曾前往泰山祭祀或游览。历代帝王均来泰山举行封禅大典。；黄河与泰山是齐鲁大地独一无二的地理坐标。黄河与泰山古有“河岳”之并称。从古至今，泰山和黄河从文化的点、线、面多个维度互动，蕴含静与动、阳与阴、时间与空间、责任与信仰的多重意象。\n见证着华夏文明的形成和发展，映照出中华民族对和谐、安宁的千年追寻。主峰玉皇顶拔地而起，海拔1545米，如天柱般屹立。\n泰山并非寻常山岳，而是华北克拉通古老基底的脊梁，其岩体形成于25亿年前的新太古代，历经五次构造运动隆升，终成“五岳独尊”。\n地质上，泰山属于鲁西隆起带，而其北侧广袤的黄河下游平原则坐落在济阳坳陷之上，一隆一陷，一刚一柔。\n二者在构造上互为镜像：山为骨，河为脉；山主静，河主动；山守恒，河创生。正是这种地质上的张力与互补，塑造了齐鲁“山河表里、刚柔相济”的独特格局。',117.1086220,36.2577770,'泰安市泰山','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山-实景-05.webp\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山-实景-11.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山-实景-18.webp\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山-实景-17.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山区__地图__04.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山-实景-10.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山-实景-09.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山-实景-13.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山-实景-12.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山-实景-03.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黄河与泰山同框_实景_03.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山-实景-16.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山-实景-15.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山-实景-14.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山-实景-04.webp\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山-实景-01.webp\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山-实景-02.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山-实景-08.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山-实景-06.webp\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山-实景-19.webp\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山-实景-07.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山-实景-20.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/泰山_实景_01.jpg\"]','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黄河与泰山同框_实景_03.jpg\"]',NULL,'泰安','2026-06-17 18:00:50','2026-07-20 18:52:33'),(15,'黄河','西晋时古黄河流经此地；陆机任平原内史时乘舟畅游黄河时做此诗，元吉降初巳。濯秽游黄河。此诗是诗人活动于德州黄河流域重要见证。',116.3074280,37.4539680,'德州市古黄河上','[\"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黄河-实景-03.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黄河大堤_实景_01.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黄河-实景-10.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黄河入海口_实景_01.jpeg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黄河号子-实景-03.webp\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/滨州黄河-实景-16.webp\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黄河号子-实景-04.jpeg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黄河-实景-12.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黄河-实景-08.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黄河-实景-04.jpeg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黄河-实景-11.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/滨州黄河-实景-14.webp\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黄河-实景-02.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/滨州黄河-实景-12.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/滨州黄河-实景-07.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/滨州黄河-实景-08.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黄河与泰山同框_实景_03.jpg\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/滨州黄河-实景-05.webp\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/滨州黄河-实景-18.webp\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黄河-实景-16.webp\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黄河号子-实景-02.JPG\", \"https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/spots/黄河-实景-09.jpeg\", \"https://shandong-lit-landscape.oss-cn-beijing.ali